import {labView,rankPanel} from './lab-ui.mjs';
import {labFor,freshLab,saveLab,saveReflection,rankFor} from './learning-labs.mjs';
import {newDraft,draftAnswer,questionForm} from './activity-ui.mjs';
import {feedbackFor} from './activities.mjs';
import {explanationChoices,saveDiscovery} from './learning-tools.mjs';
import {course,courses,allTopics,getCourse,topicById,questionById} from './course.mjs';
import {recommendation,evidence,startSession,requestHelp,submitAnswer,advance,reviewCard,localDay,activeCourse,diagnosed,chooseCourse,startMixedReview,rescueFor} from './engine.mjs';
import {openStorage,listProfiles,activeProfile,loadProfile,selectProfile,createProfile,saveProfile,deleteProfile,exportBackup,restoreBackup} from './storage.mjs';
import {companionTip,recap,followUpQuestions,shortMissions,missionReadiness,readUiPreference,writeUiPreference} from './companion.mjs';
import {faq,contextualQuestions,answerPrepared,findQuestion} from './guided-tutor.mjs';
const bundledAndroid=document.querySelector('meta[name="allen-runtime"]')?.content==='bundled-android';
const main=document.querySelector('#content'),nav=document.querySelector('#navigation'),menu=document.querySelector('#section-menu'),notice=document.querySelector('#notice');
const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state=null,view='today',busy=false,help=null,card=null,installPrompt=null,offlineReady=false,noticeTimer,chat=[],chatTopic='',missionId=null,courseQuery='',courseSubject='all',explanationResult=null;
let activityDraft=null;
const scrollPositions=new Map();let renderedView=null,renderedProfile=null;
function speechAvailable(){return 'speechSynthesis' in window&&'SpeechSynthesisUtterance' in window;}
function stopReading(){if(speechAvailable())speechSynthesis.cancel();}
const btn=(label,action,extra='',kind='')=>`<button type="button" data-action="${action}" ${extra} class="${kind}">${label}</button>`;
const topicForSession=()=>topicById((state?.session?.kind==='mixed'?null:state?.session?.topicId)??questionById(state?.session?.questionIds[state.session.index])?.topicId);
function inform(text,error=false){clearTimeout(noticeTimer);notice.textContent=text;notice.dataset.error=String(error);notice.hidden=false;noticeTimer=setTimeout(()=>notice.hidden=true,8000);}
function source(){return `<p class="source">${escape(topicForSession()?.source??activeCourse(state).source)}. Recurso de aprendizaje; no sustituye una evaluación escolar.</p>`;}
function hero(eyebrow,title,text,asset=null){asset??=view==='allen'||view==='session'&&state?.session?.phase==='lesson'?'allen-explaining-v1.png':view==='practice'||view==='notebook'?'allen-thinking-v1.png':'allen-reading.png';return `<section class="hero"><div><span class="eyebrow">${eyebrow}</span><h1>${escape(title)}</h1><p class="muted">${escape(text)}</p></div><button class="allen-companion" type="button" data-action="allen-tip" aria-label="Hablar con Allen"><img src="./assets/${asset}" width="96" height="96" alt="Allen, tu compañero educativo"></button></section>`;}
function recommendationPanel(){const r=recommendation(state);return `<section class="panel recommended"><span class="eyebrow">Tu siguiente paso</span><h2>${escape(r.title)}</h2><p>${escape(r.reason)}</p><div class="actions">${btn(r.kind==='continue'?'Continuar aprendiendo':r.kind==='diagnostic'?'Comenzar diagnóstico':r.kind==='review'?'Comenzar repaso':'Empezar lección','recommended','','primary')}</div></section>`;}
function savedPaths(){const used=courses.filter(c=>c.id===activeCourse(state).id||state.savedSessions?.[c.id]||c.topics.some(t=>state.completed.includes(t.id)));if(used.length<2)return '';return `<details class="panel"><summary>Mis caminos de aprendizaje · ${used.length}</summary><p class="small muted">Cada materia conserva su avance. Puedes alternar estudio, práctica y repaso.</p>${used.map(c=>`<div class="profile-item"><span><strong>${escape(c.subject)}</strong><small> · ${c.topics.filter(t=>state.completed.includes(t.id)).length}/${c.topics.length} temas${state.savedSessions?.[c.id]?' · Actividad pendiente':''}</small></span>${btn('Ver camino','choose-course',`data-course="${c.id}"`)}</div>`).join('')}</details>`;}
function today(){const selected=activeCourse(state);const completed=selected.topics.filter(t=>state.completed.includes(t.id)).length;const count=state.events.filter(e=>e.type==='answer').length;return hero(state.profile.goal==='school'?'Apoyo escolar':'Aprender algo nuevo',`Hola, ${state.profile.name}`,'Estudia y practica a tu ritmo')+recommendationPanel()+savedPaths()+`<div class="grid home-metrics"><section class="panel"><span class="metric">${completed}/${selected.topics.length}</span><span class="small">Temas comprobados</span></section><section class="panel"><span class="metric">${count}</span><span class="small">Respuestas registradas</span></section></div><section class="panel course-summary"><div><h2>${escape(selected.title)}</h2><p class="small muted">${escape(selected.subject)} · ${courses.length} rutas disponibles</p></div><div class="actions">${btn('Ver mi curso','view','data-target="learn"','secondary')}${btn('Terminar por hoy','finish-day')}</div></section><p class="small muted privacy-line">Progreso en tu dispositivo · sin anuncios ni telemetría</p>`;}
function filteredCourses(){const query=courseQuery.trim().toLocaleLowerCase('es');return courses.filter(c=>(courseSubject==='all'||c.subject===courseSubject)&&`${c.title} ${c.subject} ${c.topics.map(t=>`${t.title} ${t.objective} ${t.example}`).join(' ')}`.toLocaleLowerCase('es').includes(query));}
function courseCards(){const list=filteredCourses();return list.length?list.map(c=>`<article class="course-card ${activeCourse(state).id===c.id?'selected':''}"><img src="./assets/${'allen-reading.png'}" alt="" width="90" height="90"><span class="eyebrow">${escape(c.subject)}</span><h3>${escape(c.title)}</h3><p class="small muted">${new Set(c.topics.map(t=>t.module)).size} módulos · ${c.topics.length} lecciones · ${c.topics.filter(t=>state.completed.includes(t.id)).length} comprobadas</p>${state.savedSessions?.[c.id]?'<span class="badge">Actividad guardada</span>':''}${btn(activeCourse(state).id===c.id?'Ver ruta activa':'Elegir este curso','choose-course',`data-course="${c.id}"`,'secondary')}</article>`).join(''):'<p>No encontramos esa búsqueda. Prueba otra palabra o elige todas las áreas.</p>';}
function catalogue(){return `<section class="catalogue"><h2>¿Qué quieres aprender?</h2><p class="catalogue-summary">${courses.length} rutas · ${allTopics.length} lecciones · ${courses.reduce((n,c)=>n+new Set(c.topics.map(t=>t.module)).size,0)} módulos para reforzar</p><div class="course-filters"><label class="field">Buscar un objetivo<input id="course-search" type="search" maxlength="80" value="${escape(courseQuery)}" placeholder="Ejemplo: cuentas, plantas, inglés"></label><label class="field">Área de aprendizaje<select id="course-subject"><option value="all">Todas las áreas</option>${courses.map(c=>`<option ${courseSubject===c.subject?'selected':''}>${escape(c.subject)}</option>`).join('')}</select></label></div><div class="catalogue-controls"><span>Elige una materia y sigue su camino</span><div>${btn('‹','courses-scroll','data-direction="-1" aria-label="Ver cursos anteriores"')}${btn('›','courses-scroll','data-direction="1" aria-label="Ver cursos siguientes"')}</div></div><div class="course-grid" aria-live="polite">${courseCards()}</div></section>`;}
function missions(){return `<section class="panel"><span class="eyebrow">Retos para aplicar lo aprendido</span><h2>Misiones para la vida real</h2><p class="muted">Tres decisiones, pistas y una comprobación. Prepara las bases indicadas antes de empezar; puedes avanzar a tu ritmo.</p><div class="mission-list">${shortMissions.map(m=>{const t=topicById(m.topicId),ready=missionReadiness(state,m);return `<article><img src="./assets/${m.asset}" width="56" height="56" alt="Allen te guía"><h3>${escape(m.title)}</h3><p class="small">${escape(m.description)}</p>${ready?btn('Resolver misión','short-mission',`data-mission="${m.id}"`,'secondary'):`<p class="small muted">${diagnosed(state,t.courseId)?`Primero comprueba ${escape(topicById(t.prerequisite)?.title??t.title)}.`:'Primero realiza el diagnóstico de esta ruta.'}</p>${btn('Preparar esta misión','prepare-mission',`data-mission="${m.id}"`,'secondary')}`}</article>`;}).join('')}</div></section>`;}
function companionPanel(){const tip=companionTip(state,view),minimized=readUiPreference(`allen-companion:${state.profile.id}`,false);return `<aside class="companion-card ${minimized?'companion-small':''}" aria-label="Allen te acompaña"><img src="./assets/${tip.asset}" alt="Allen" width="52" height="52"><div ${minimized?'hidden':''}><strong>${escape(tip.title)}</strong><p>${escape(tip.text)}</p></div>${btn(minimized?'Ver consejo':'Minimizar','toggle-companion',`aria-expanded="${!minimized}"`)}${minimized?'':btn('Hablar','view','data-target="allen"')}</aside>`;}
function summary(){const r=recap(state);return hero('Cerramos por hoy','Tu aprendizaje queda contigo',r.encouragement,r.checked.length?'allen-celebrate.png':'allen-reading.png')+`<section class="panel"><h2>Lo que hiciste hoy</h2><p>${escape(r.text)}</p>${r.reinforce.length?`<p>Conviene reforzar: ${escape(r.reinforce.join(', '))}.</p>`:'<p>Podemos seguir construyendo sobre lo que has practicado.</p>'}<h3>Cuando vuelvas</h3><p>${escape(r.next.title)}. ${escape(r.next.reason)}</p><p class="small muted">Puedes cerrar la app. Tu actividad se guarda después de cada respuesta.</p><div class="actions">${btn('Volver a Hoy','view','data-target="today"','primary')}${btn('Configurar recordatorios','view','data-target="settings"')}</div></section>`;}
function reminderSettings(){const bridge=window.AllenReminders;return `<section class="panel"><h2>Recordatorios de Allen</h2><p>Un recordatorio diario, a la hora que elijas, sin anuncios ni presión. Está desactivado hasta que lo solicites.</p>${bridge?`<form id="reminder-form"><label class="field">Hora del recordatorio<input name="time" type="time" value="${escape(readUiPreference('allen-reminder-time','18:00'))}" required></label><button type="submit" class="primary">Activar recordatorios</button></form>${btn('Desactivar recordatorios','disable-reminders')}<p id="reminder-status" role="status">${escape(reminderStatus||window.AllenReminders?.status?.()||'Pulsa Activar para solicitar el permiso.')}</p><p class="small muted">Android puede retrasarlo por ahorro de batería. Los detalles del progreso se marcan como privados para la pantalla bloqueada. Si fuerzas la detención, abre ALLEN otra vez para reactivarlo.</p>`:'<p>Los recordatorios con la app cerrada se incluyen en la APK de Android. En esta vista web puedes consultar tu cierre y tus repasos dentro de ALLEN.</p>'}</section>`;}
function settings(){return hero('Ajustes','Tu forma de aprender','Controla el acompañamiento y los recordatorios.')+accessibilitySettings()+reminderSettings()+`<section class="panel"><h2>Guía y perfiles</h2>${btn('Abrir perfiles y recorrido','view','data-target="profiles"')}${btn('Preferencias de aprendizaje','view','data-target="progress"')}</section>`;}
let reminderStatus='';
function rememberClose(){if(!state)return;const r=recap(state);try{window.AllenReminders?.saveSummary(`${r.text} Próximo paso: ${r.next.title}.`);}catch{/* Native bridge is optional. */}}
window.addEventListener('allen-background',rememberClose);
window.addEventListener('allen-close-request',()=>{rememberClose();if(state){view='summary';render();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){stopReading();rememberClose();}});
window.allenNavigateBack=()=>{if(busy)return true;if(!state||view==='today'||view==='summary')return false;view=view==='session'?'learn':view==='notebook'&&state.session&&state.session.phase!=='complete'?'session':'today';guarded(()=>render());return true;};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state&&(state.preferences?.theme??'system')==='system')render({focus:false});});
window.addEventListener('allen-file-status',e=>inform(String(e.detail)));
window.addEventListener('allen-reminder-status',e=>{reminderStatus=String(e.detail);if(view==='settings')render({focus:false});});
function learningMap(){const c=activeCourse(state);return `<section class="panel"><h2>Tu mapa de aprendizaje</h2><details><summary>Ver bases y temas de esta ruta</summary><ol class="learning-map">${c.topics.map(t=>{const done=state.completed.includes(t.id),ready=diagnosed(state,c.id)&&(!t.prerequisite||state.completed.includes(t.prerequisite));return `<li><strong>${escape(t.title)}</strong><span class="badge">${done?'Comprobado':ready?'Tu siguiente base':'Base pendiente'}</span><p class="small muted">${done?'Puedes aplicar y repasar.':t.prerequisite?`Primero comprueba: ${escape(topicById(t.prerequisite).title)}.`:'El diagnóstico orienta esta primera lección.'}</p></li>`;}).join('')}</ol></details></section>`;}
function moduleRoutes(selected){return [...new Set(selected.topics.map(t=>t.module))].map((label,i)=>{const topics=selected.topics.filter(t=>t.module===label),done=topics.filter(t=>state.completed.includes(t.id)).length;return `<details class="route-module" ${i===0?'open':''}><summary>${escape(label)} · ${done}/${topics.length}</summary><div class="module-lessons">${topics.map(t=>{const unlocked=diagnosed(state)&&(!t.prerequisite||state.completed.includes(t.prerequisite));return `<article><h3>${escape(t.title)}</h3><p class="small">${escape(t.objective)}</p><span class="badge">${state.completed.includes(t.id)?'Comprobado':unlocked?'Disponible':'Base pendiente'}</span>${unlocked?btn(state.completed.includes(t.id)?'Repasar tema':'Abrir lección','start',`data-topic="${t.id}" data-kind="${state.completed.includes(t.id)?'review':'learn'}"`,'secondary'):`<p class="small muted">${diagnosed(state)&&t.prerequisite?`Primero: ${escape(topicById(t.prerequisite).title)}`:'Primero realiza el diagnóstico.'}</p>`}</article>`;}).join('')}</div></details>`;}).join('');}
function learn(){const selected=activeCourse(state);const completed=selected.topics.filter(t=>state.completed.includes(t.id)).length;return hero('Aprender','Encuentra tu próxima meta','Elige una ruta y avanza a tu ritmo.')+catalogue()+`<section class="panel active-route"><div><span class="badge">Tu ruta</span><h2>${escape(selected.title)}</h2><p class="small muted">${completed} de ${selected.topics.length} temas comprobados</p></div><div>${btn(diagnosed(state)?'Continuar mi ruta':'Hacer diagnóstico','recommended','','primary')}</div><details class="route-details"><summary>Ver las ${selected.topics.length} lecciones</summary><div class="route-list">${moduleRoutes(selected)}</div></details></section>`;}
function practice(){return hero('Recuerda y aplica','Practicar también es aprender','Refuerza tu siguiente tema o recupera lo que ya estudiaste.')+recommendationPanel()+mixedPanel()+`<details class="panel"><summary>Misiones de aplicación</summary>${missions()}</details><details class="panel"><summary>Reforzar mis dificultades</summary>${errorsPanel()}</details>`+`<section class="panel"><h2>Tarjetas de repaso</h2><p class="muted">Responde mentalmente antes de ver la explicación.</p>${state.completed.length?allTopics.filter(t=>state.completed.includes(t.id)).map(t=>`<div class="profile-item"><span>${t.title}<small class="muted"> · ${state.cards[t.id]?.due?`Repaso: ${escape(state.cards[t.id].due)}`:'Lista para repasar'}</small></span>${btn('Repasar tarjeta','card',`data-topic="${t.id}"`)}</div>`).join(''):'<p>Las tarjetas se habilitan al superar la comprobación de cada lección.</p>'}</section>${card?`<section class="panel"><h2>${escape(topicById(card.id).card.front)}</h2>${card.revealed?`<p class="card-answer">${escape(topicById(card.id).card.back)}</p><div class="actions">${btn('Necesito repasarlo','card-result','data-remembered="false"')}${btn('Lo recordé','card-result','data-remembered="true"','primary')}</div>`:btn('Ver explicación','reveal-card','','secondary')}</section>`:''}`;}
function helpPanel(){return help?`<section class="panel tutor-help" id="help-panel" role="status"><span class="badge">Explicación preparada</span><h2>Vamos paso a paso</h2><p>${escape(help.text)}</p><p class="source">${escape(help.source)}</p></section>`:'';}
function helpButtons(hints=false){return `<div class="actions">${btn('No entendí','help','data-help="explain"')}${btn('Dame otro ejemplo','help','data-help="alternative"')}${btn('Explícalo más sencillo','help','data-help="simple"')}${hints?btn('Dame una pista','help','data-help="hint"'):''}</div>`;}
function allen(){const t=topicById(chatTopic)??topicForSession()??activeCourse(state).topics[0];const suggestions=contextualQuestions(state,t.id),primary=[{...suggestions[1],label:'No entendí'},{...suggestions[2],label:'Dame un ejemplo'},{id:'context:status',label:'¿Cómo voy?'},{id:'context:recommend',label:'¿Qué hago después?'}],secondary=suggestions.filter(q=>!primary.some(p=>p.id===q.id));return hero('Allen · tutor guiado','¿Qué vamos a entender hoy?','Elige una pregunta. Tengo explicaciones y ejemplos de todas las rutas, listos sin conexión.')+`<section class="panel"><label class="field">Tema que quieres entender<select id="chat-topic">${courses.map(c=>`<optgroup label="${escape(c.title)}">${c.topics.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${escape(x.title)}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="actions question-chips">${primary.map(q=>btn(escape(q.label),'ask-prepared',`data-question="${q.id}"`,'secondary')).join('')}</div><details><summary>Más formas de ayudarte</summary><div class="actions">${secondary.map(q=>btn(escape(q.label),'ask-prepared',`data-question="${q.id}"`,'secondary')).join('')}</div></details></section><section class="panel" aria-label="Conversación con Allen"><div class="guided-conversation" role="log" aria-live="polite">${chat.length?chat.map(m=>`<article class="chat-message"><img src="./assets/allen-reading.png" width="56" height="56" alt="Allen te acompaña"><div><h3>${escape(m.question)}</h3><p class="worked-example">${escape(m.text)}</p><p class="source">${escape(m.source)}</p><div class="actions follow-up">${(m.followUps??[]).map(q=>btn(escape(q.label),'ask-prepared',`data-question="${q.id}"`,'secondary')).join('')}</div></div></article>`).join(''):'<p>Estoy contigo. ¿Prefieres entender la idea, ver un ejemplo o revisar tu siguiente paso?</p>'}</div><form id="guided-form"><label class="field">También puedes escribir una duda breve<input name="message" maxlength="300" required placeholder="Ejemplo: ¿cómo se guarda mi progreso?"></label><button type="submit" class="primary">Preguntar a Allen</button></form><p class="small muted">Respuestas preparadas; no se envían preguntas ni se guardan conversaciones.</p>${chat.length?btn('Limpiar conversación','clear-chat'):''}</section><details class="panel"><summary>Preguntas sobre ALLEN y cómo aprender</summary><div class="actions">${faq.map(q=>btn(escape(q.label),'ask-prepared',`data-question="${q.id}"`)).join('')}</div></details>`+helpPanel();}
async function askPrepared(id,label){let reply=answerPrepared(state,id??'unknown',chatTopic);if(reply.action){const s=state.session;const q=questionById(s?.questionIds[s?.index]);const canHint=s?.phase==='practice'&&!s.answers.some(a=>a.questionId===q?.id);if(reply.action!=='hint'||canHint){let result;await mutate(next=>{result=requestHelp(next,reply.action);});reply={...reply,...result,text:id==='context:first-step'?`Primer paso de tu actividad: ${result.text}`:result.text};}}chat.push({question:label,text:reply.text,source:reply.source,followUps:followUpQuestions(id,reply.topicId||(chatTopic||topicForSession()?.id||activeCourse(state).topics[0].id))});chat=chat.slice(-12);await render({focus:false});main.querySelector('.chat-message:last-child')?.scrollIntoView({block:'nearest'});}
function errorsPanel(){const ids=[...new Set(state.events.filter(e=>e.type==='answer'&&!e.correct).slice(-20).reverse().map(e=>e.questionId))];return `<section class="panel"><h2>Aprende de tus errores</h2><p class="muted">Un error es una pista sobre qué reforzar. Aquí tienes tus últimas dificultades.</p>${ids.length?ids.slice(0,5).map(id=>{const q=questionById(id),t=topicById(q.topicId);return `<details><summary>${escape(t.title)} · ${escape(q.prompt)}</summary><p>${escape(q.feedback)}</p>${btn('Reforzar este tema','start',`data-topic="${t.id}" data-kind="review"`,'secondary')}</details>`;}).join(''):'<p>Aún no hay errores registrados en este perfil. Cuando aparezcan, encontrarás aquí explicaciones concretas.</p>'}</section>`;}
const statusLabels={new:'Sin evidencia',learning:'Aprendiendo',practicing:'Practicando',mastered:'Dominio con evidencia',needs_reinforcement:'Necesita refuerzo',reviewing:'Repaso pendiente'};
function progress(){return hero('Evidencia, no solo porcentajes','Tu progreso tiene una historia','Los intentos, las ayudas y las comprobaciones explican cada recomendación.')+`<section class="panel"><h2>Cuaderno de descubrimientos</h2><p>Ideas y errores comprendidos, guardados solo en este perfil.</p>${btn('Abrir mi cuaderno','view','data-target="notebook"')}</section>`+rankPanel(state)+learningMap()+activeCourse(state).topics.map(t=>{const e=evidence(state,t.id);return `<details class="panel"><summary>${escape(t.title)} · <span class="badge">${statusLabels[e.status]}</span></summary><p><strong>${e.score}%</strong> de dominio estimado · confianza de evidencia ${e.confidence}%</p><progress value="${e.score}" max="100" aria-label="Dominio estimado de ${t.title}"></progress><ul class="evidence-list"><li>${e.correct} aciertos / ${e.attempts} intentos</li><li>${e.incorrect} errores</li><li>${e.hints} pistas utilizadas</li><li>${e.explanations} explicaciones solicitadas</li><li>${e.quiz_count} comprobaciones</li><li>${state.completed.includes(t.id)?'Objetivo comprobado':'Objetivo pendiente'}</li></ul><p class="small muted">Próximo repaso: ${e.next_review??'Se programa al terminar la práctica'}.</p><details><summary>¿Cómo se calcula?</summary><p class="small">Usamos la misma fórmula de dominio que ALLEN de escritorio: aciertos, cantidad de evidencia, dificultad, actividad reciente y pistas. Es una estimación de aprendizaje, no una nota oficial. Repetir preguntas conocidas puede elevarla sin demostrar transferencia.</p></details></details>`;}).join('')+`<section class="panel"><h2>Protege tu progreso</h2><p>La copia contiene solo este perfil. Guárdala en un lugar privado; no está cifrada.</p><div class="actions">${btn('Exportar mi progreso','export','','secondary')}${btn('Recuperar una copia','import')}</div><p class="small muted">Recuperar crea otro perfil y conserva los existentes. Borrar datos del navegador puede eliminar el progreso local.</p></section><section class="panel"><h2>Tu forma de aprender</h2><form id="preferences-form"><label class="field">Nombre o apodo<input type="text" name="name" maxlength="40" required value="${escape(state.profile.name)}"></label>${subjectChoice(activeCourse(state).id)}<label class="field">Tamaño del texto<select name="textSize"><option value="normal">Normal</option><option value="large" ${state.preferences?.textSize==='large'?'selected':''}>Grande</option></select></label><button type="submit" class="primary">Guardar preferencias</button></form><p class="small muted">Sin cobros ni anuncios. Allen explica y guía con contenido preparado, sin Internet ni modelos externos.</p></section>`;}
function session(){
 const s=state.session;if(!s){view='today';return today();}
 const topic=topicForSession();
 const mission=shortMissions.find(m=>m.id===missionId&&m.topicId===topic.id);
 if(s.phase==='complete'&&s.kind==='mixed')return hero('Repaso combinado','Elige la estrategia, no solo la respuesta',`${s.answers.filter(a=>a.correct).length} de ${s.answers.length} aciertos. Tus intentos y próximos repasos quedaron guardados.`)+`<section class="panel"><p>Este repaso combina temas comprobados; no desbloquea temas nuevos.</p>${btn('Volver a Practicar','view','data-target="practice"','primary')}</section>`;
 if(s.phase==='complete'){
  const correct=s.answers.filter(a=>a.correct).length;const passed=s.kind!=='diagnostic'&&s.answers.at(-1).correct&&correct>=2;
  return hero(s.kind==='diagnostic'?'Punto de partida guardado':'Sesión guardada',s.kind==='diagnostic'?'Ya tenemos una primera orientación':passed?'Un paso más en tu aprendizaje':'Vamos a reforzar este tema',`${correct} de ${s.answers.length} respuestas correctas. Puedes seguir sin prisa.`,passed?'allen-celebrate.png':'allen-reading.png')+`<section class="panel"><h2>${s.kind==='diagnostic'?'Tu ruta empieza aquí':passed?'Comprobación superada':'La comprobación necesita otra práctica'}</h2><p>${s.kind==='diagnostic'?'El diagnóstico añade evidencia. Incluso si acertaste, comprobaremos tu comprensión con ejemplos nuevos.':passed?'Tu objetivo está comprobado y el repaso queda programado.':'Los errores ayudan a elegir la siguiente explicación. El tema no se marca como completado.'}</p>${s.kind==='diagnostic'?getCourse(s.courseId??course.id).topics.map(t=>{const answers=s.answers.filter(a=>questionById(a.questionId).topicId===t.id);return `<p class="small">${t.title}: ${answers.length?`${answers.filter(a=>a.correct).length}/${answers.length} · ${answers.every(a=>a.correct)?'Base inicial fuerte':'Conviene practicar'}`:'Se comprueba durante la ruta'}</p>`;}).join(''):''}<div class="actions">${btn('Ver mi siguiente paso','view','data-target="today"','primary')}${btn('Ver mi progreso','view','data-target="progress"')}${btn('Terminar por hoy','finish-day')}</div></section>`+(s.kind==='diagnostic'?'':explainPanel(topic));
 }
 if(s.phase==='lesson'){
  const e=evidence(state,topic.id);const simple=state.profile.level==='bases'||e.score<50;
  return hero(mission?'Misión de aprendizaje':'Lección breve',mission?.title??topic.title,mission?.intro??topic.objective)+`<section class="panel"><span class="badge">${simple?'Explicación con apoyo':'Explicación y aplicación'}</span>${labView(topic,state,simple)}${speechAvailable()?btn('Leer explicación','read-lesson'):''}${btn('Anotar una idea','note-topic',`data-topic="${topic.id}"`)}${helpButtons()}${source()}<div class="actions">${btn('Entendido, vamos a practicar','advance','','primary')}</div></section>`+helpPanel();
 }
 const q=questionById(s.questionIds[s.index]);if(activityDraft?.questionId!==q.id)activityDraft=newDraft(q);const answer=s.answers.find(a=>a.questionId===q.id);const hintCount=s.hints.filter(id=>id===q.id).length;
 return hero(s.kind==='diagnostic'?'Diagnóstico breve':q.kind==='check'?'Comprueba lo que aprendiste':'Práctica guiada',s.kind==='diagnostic'?`Pregunta ${s.index+1} de ${s.questionIds.length}`:topic.title,s.kind==='diagnostic'?'Responde lo que puedas. Aquí descubrimos dónde empezar.':q.kind==='check'?'Aplica la idea en una situación nueva.':'Inténtalo primero; puedes pedir ayuda.')+`<section class="panel"><p class="small muted">${s.kind==='diagnostic'?topic.title:`Actividad ${s.index+1} de ${s.questionIds.length}`}</p><h2>${q.prompt}</h2>${answer?`<div class="feedback ${answer.correct?'':'error'}" role="status"><strong>${answer.correct?'Lo razonaste bien':'Revisemos la idea'}</strong><p>Tu respuesta: ${escape(answer.answer)}</p><p>${escape(feedbackFor(q,answer.answer).text)}</p></div><div class="actions">${btn(s.index===s.questionIds.length-1?'Terminar y guardar':'Siguiente actividad','advance','','primary')}</div>`:`${questionForm(q,activityDraft)}${helpButtons(true)}${btn('Hablar con Allen sobre esto','chat-current','','secondary')}<p class="small muted">${hintCount} de ${q.hints.length} pistas utilizadas.</p>`}${answer&&!answer.correct?btn('Guardar lo que comprendí','note-error',`data-topic="${topic.id}"`):''}${source()}</section>`+rescuePanel()+helpPanel();
}
function backup(){return hero('Copia manual de progreso','Guarda tu aprendizaje','Selecciona y copia este texto JSON en un archivo privado .json. Podrás recuperarlo con Importar una copia.')+`<section class="panel"><label class="field">Tu copia local<textarea rows="12" readonly>${escape(exportBackup(state))}</textarea></label><p class="small muted">Si el selector de Android no está disponible, esta copia manual permite conservar tu progreso. La copia contiene únicamente este perfil y no está cifrada.</p>${btn('Volver a mi progreso','view','data-target="progress"')}</section>`;}
function subjectChoice(selected='fractions-v1'){return `<label class="field">¿Qué quieres aprender?<select name="course">${courses.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${escape(c.subject)} · ${escape(c.title)}</option>`).join('')}</select><small>Puedes cambiar de materia y retomar cada camino cuando quieras.</small></label>`;}
function profileForm(){return `<section class="panel"><h2>Un espacio para aprender</h2><form id="profile-form"><label class="field">¿Cómo quieres que te llame?<input name="name" type="text" maxlength="40" required autocomplete="off" placeholder="Nombre o apodo"><small>No necesitas usar tu nombre real.</small></label><label class="field">¿Qué quieres hacer?<select name="goal"><option value="school">Reforzar lo que aprendo en la escuela</option><option value="explore">Aprender algo nuevo por mi cuenta</option></select></label><label class="field">¿Dónde quieres empezar?<select name="level"><option value="bases">Quiero entender las bases</option><option value="practice">Ya conozco algo y quiero practicar</option><option value="challenge">Quiero comprobar lo que sé</option></select></label>${subjectChoice()}<p class="small muted">El diagnóstico ajusta el apoyo. No pedimos edad, correo ni escuela.</p><button type="submit" class="primary">Crear mi perfil</button></form></section>`;}
async function profiles(){menu.hidden=true;menu.open=false;const list=await listProfiles(db);main.innerHTML=hero('Perfiles locales','Tu espacio, en este dispositivo','Los perfiles separan el progreso. Cualquier persona con acceso a este navegador puede abrirlos.')+`<section class="panel"><h2>Elegir perfil</h2>${list.length?list.map(s=>`<div class="profile-item"><span><strong>${escape(s.profile.name)}</strong><small class="muted"> · ${s.completed.length}/${allTopics.length} temas</small></span><div class="row">${btn('Abrir','select-profile',`data-id="${s.profile.id}"`)}${btn('Eliminar','confirm-delete',`data-id="${s.profile.id}"`,'danger')}</div></div>`).join(''):'<p>Aún no hay perfiles.</p>'}</section>`+(state?`<section class="panel"><h2>La materia de ${escape(state.profile.name)}</h2><p class="badge">Rango: ${escape(rankFor(state).current.title)}</p><form id="learning-choice-form">${subjectChoice(activeCourse(state).id)}<button type="submit" class="primary">Cambiar materia</button></form></section>`:'')+profileForm()+`<section class="panel"><h2>Recuperar progreso</h2>${btn('Importar una copia local','import')}<p class="small muted">No subimos el archivo a Internet. No importamos cursos ni instrucciones de IA.</p></section>`;nav.hidden=true;main.focus();}
async function render({focus=true}={}){
 nav.hidden=!state;menu.hidden=!state;menu.open=false;
 if(!state||view==='profiles'){stopReading();await profiles();androidExtras?.rendered({view:'profiles',profile:state?.profile,main});return;}
 const changed=renderedView!==view||renderedProfile!==state.profile.id;
 if(renderedProfile!==state.profile.id){activityDraft=null;scrollPositions.clear();noteTopic='';noteUnderstood=false;explanationResult=null;rescuePracticeResult=null;}
 if(renderedView&&renderedProfile===state.profile.id)scrollPositions.set(renderedView,window.scrollY);
 if(changed)stopReading();
 document.documentElement.dataset.textSize=state.preferences?.textSize??'normal';
 const theme=state.preferences?.theme??'system';document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;
 document.documentElement.dataset.reduceMotion=String(state.preferences?.reduceMotion??false);
 document.querySelector('#current-section').textContent=({today:'Hoy',learn:'Aprender',practice:'Practicar',allen:'Allen',progress:'Mi progreso',session:'Actividad',backup:'Copia',summary:'Cierre',settings:'Ajustes',notebook:'Cuaderno'})[view]??'Hoy';
 const openSections=!changed?new Set([...main.querySelectorAll('details[open]')].map(d=>d.querySelector(':scope > summary')?.textContent)):new Set();
 const currentScroll=window.scrollY;
 const screens={today,learn,practice,allen,progress,session,backup,summary,settings,notebook};main.innerHTML=(screens[view]??today)()+ (view==='summary'||view==='settings'?'':companionPanel());
 for(const section of main.querySelectorAll('details'))if(openSections.has(section.querySelector(':scope > summary')?.textContent))section.open=true;
 for(const button of nav.querySelectorAll('button')){if(button.dataset.view===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}
 if(focus)main.focus({preventScroll:true});
 window.scrollTo({top:changed?(scrollPositions.get(view)??0):currentScroll,behavior:'instant'});
 renderedView=view;renderedProfile=state.profile.id;
 androidExtras?.rendered({view,profile:state.profile,main});
}
async function mutate(fn){const next=structuredClone(state);fn(next);state=await saveProfile(db,next);}
async function guarded(fn){if(busy)return;busy=true;main.setAttribute('aria-busy','true');document.querySelectorAll('button, #content [data-lab-value]').forEach(b=>b.disabled=true);try{await fn();}catch(error){inform(error.message??'No se pudo completar la acción. Tu progreso anterior sigue guardado.',true);}finally{busy=false;main.removeAttribute('aria-busy');document.querySelectorAll('button, #content [data-lab-value]').forEach(b=>b.disabled=b.dataset.boundary==='true');}}
async function importFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>guarded(async()=>{const file=input.files[0];if(!file)return;if(file.size>2_000_000)throw Error('La copia supera el límite de 2 MB.');state=await restoreBackup(db,await file.text());view='today';help=null;card=null;chat=[];chatTopic='';missionId=null;window.AllenReminders?.clearSummary();await render();inform('Copia recuperada como un perfil nuevo.');});input.click();}
async function perform(button){
 const action=button.dataset.action;
 if(action==='toggle-companion'){const key=`allen-companion:${state.profile.id}`;writeUiPreference(key,!readUiPreference(key,false));await render({focus:false});return;}
 if(action==='finish-day'){rememberClose();view='summary';await render();return;}
 if(action==='disable-reminders'){window.AllenReminders?.disable();return;}
 if(action==='short-mission'||action==='prepare-mission'){const m=shortMissions.find(m=>m.id===button.dataset.mission);if(!m)return;const t=topicById(m.topicId);if(state.session&&state.session.phase!=='complete'){view='session';inform('Continúa primero tu actividad guardada.');}else if(action==='short-mission'){await mutate(s=>startSession(s,state.completed.includes(t.id)?'review':'learn',t.id));missionId=m.id;view='session';help=null;}else{await mutate(s=>chooseCourse(s,t.courseId));view='learn';missionId=null;inform(`Vamos a preparar las bases para ${m.title.toLowerCase()}.`);}await render();return;}
 if(action?.startsWith('lab-')){const topic=topicForSession();if(!topic||state.session?.phase!=='lesson')throw Error('Abre una lección para explorar.');const lab=state.learningLabs?.[topic.id]??freshLab(topic),patch={};
  if(action==='lab-tab')patch.step=Number(button.dataset.step);
  if(action==='lab-color')patch.values=[lab.values[0]===Number(button.dataset.count)?0:Number(button.dataset.count),lab.values[1],lab.values[2]];
  if(action==='lab-piece'){const n=Number(button.dataset.piece),tokens=labFor(topic).sentence??labFor(topic).timeline??labFor(topic).pairs;if(n<0||n>=tokens.length||lab.built.includes(n))return;patch.built=[...lab.built,n];}
  if(action==='lab-mark'){const n=Number(button.dataset.mark);patch.built=lab.built.includes(n)?lab.built.filter(i=>i!==n):[...lab.built,n];}
  if(action==='lab-reset')patch.built=[];
  if(action==='lab-move')patch.values=[Math.max(-2,Math.min(2,lab.values[0]+Number(button.dataset.dx))),Math.max(-2,Math.min(2,lab.values[1]+Number(button.dataset.dy))),lab.values[2]];
  if(action==='lab-condition')patch.values=[lab.values[0],lab.values[1],Number(button.dataset.condition)];
  await mutate(s=>saveLab(s,topic.id,patch));await render({focus:false});if(action==='lab-tab')main.querySelector(`[data-action=lab-tab][data-step="${patch.step}"]`)?.focus({preventScroll:true});return;
 }
 if(action==='move-step'){const q=questionById(state.session?.questionIds[state.session.index]),i=Number(button.dataset.index),j=i+Number(button.dataset.direction);if(!q||q.activity!=='order'||j<0||j>=activityDraft.order.length)return;[activityDraft.order[i],activityDraft.order[j]]=[activityDraft.order[j],activityDraft.order[i]];await render({focus:false});main.querySelector(`button[data-action=move-step][data-index="${j}"][data-direction="${button.dataset.direction}"]`)?.focus({preventScroll:true});inform(`Paso movido a la posición ${j+1}.`);return;}
 if(action==='chat-current'){chatTopic=topicForSession()?.id??'';view='allen';await render();return;}
 if(action==='ask-prepared'){await askPrepared(button.dataset.question,button.textContent);return;}
 if(action==='clear-chat'){chat=[];await render();return;}
 if(action==='mixed-review'){chatTopic='';activityDraft=null;await mutate(s=>startMixedReview(s));explanationResult=null;view='session';help=null;await render();return;}
 if(action==='note-topic'||action==='note-error'){noteTopic=button.dataset.topic;view='notebook';if(action==='note-error')noteUnderstood=true;await render();return;}
 if(action==='rescue'){let result;await mutate(s=>{result=requestHelp(s,'simple');});help={...result,text:`${result.text} Otro ejemplo: ${rescueFor(state)?.topic.alternative??''}`};await render({focus:false});return;}
 if(action==='rescue-base'){const r=rescueFor(state);help={text:`Recordemos la base: ${r.base.simple} Ejemplo: ${r.base.example}`,source:r.base.source};await render({focus:false});return;}
 if(action==='read-lesson'){stopReading();const t=topicForSession(),utterance=new SpeechSynthesisUtterance(`${t.simple} Ejemplo: ${t.example}`);utterance.lang='es';const voices=speechSynthesis.getVoices();const local=voices.find(v=>v.localService&&v.lang.startsWith('es'));if(!local){inform('No hay una voz española local disponible. Puedes usar la explicación escrita.');return;}utterance.voice=local;utterance.onerror=()=>inform('La lectura no está disponible. La explicación escrita sigue aquí.');speechSynthesis.speak(utterance);return;}
 if(action==='stop-reading'){stopReading();return;}
 if(action==='view'){view=button.dataset.target;await render();return;}
 if(action==='choose-course'){if(activeCourse(state).id===button.dataset.course){view='learn';await render();main.querySelector('.route-details').open=true;main.querySelector('.active-route')?.scrollIntoView({block:'start'});return;}await mutate(s=>chooseCourse(s,button.dataset.course));view='learn';help=null;card=null;await render();return;}
 if(action==='recommended'){
  chatTopic='';activityDraft=null;
  const r=recommendation(state);if(r.kind!=='continue')await mutate(s=>startSession(s,r.kind==='diagnostic'?'diagnostic':r.kind==='review'?'review':'learn',r.topicId??null));help=null;view='session';await render();return;
 }
 if(action==='start'){chatTopic='';activityDraft=null;if(state.session&&state.session.phase!=='complete'){view='session';inform('Primero continúa tu actividad guardada.');}else{await mutate(s=>startSession(s,button.dataset.kind,button.dataset.topic));view='session';help=null;}await render();return;}
 if(action==='resume'){view='session';await render();return;}
 if(action==='advance'){explanationResult=null;rescuePracticeResult=null;await mutate(s=>advance(s));help=null;view='session';await render();return;}
 if(action==='help'){let result;await mutate(s=>{result=requestHelp(s,button.dataset.help);});help=result;await render({focus:false});document.querySelector('#help-panel')?.scrollIntoView({block:'nearest'});return;}
 if(action==='card'){card={id:button.dataset.topic,revealed:false};await render();return;}
 if(action==='reveal-card'){card.revealed=true;await render();return;}
 if(action==='card-result'){await mutate(s=>reviewCard(s,card.id,button.dataset.remembered==='true'));card=null;await render();inform('Repaso guardado y próxima fecha programada.');return;}
 if(action==='courses-scroll'){const shelf=main.querySelector('.course-grid');shelf.scrollBy({left:Number(button.dataset.direction)*shelf.clientWidth*.8,behavior:state.preferences?.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
 if(action==='allen-tip'){inform(state?`Vamos paso a paso. ${recommendation(state).reason}`:'Hola, soy Allen. Crea tu espacio para aprender conmigo.');const companion=main.querySelector('.allen-companion');if(!state?.preferences?.reduceMotion)companion?.classList.add('wave');setTimeout(()=>companion?.classList.remove('wave'),650);return;}
 if(action==='export'){if(window.AllenFiles?.exportProgress){window.AllenFiles.exportProgress(exportBackup(state));return;}if(bundledAndroid){view='backup';await render();return;}const url=URL.createObjectURL(new Blob([exportBackup(state)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='allen-progreso.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);inform('Copia generada. Guárdala en un lugar privado.');return;}
 if(action==='import'){await importFile();return;}
 if(action==='select-profile'){await selectProfile(db,button.dataset.id);state=await loadProfile(db,button.dataset.id);scrollPositions.clear();noteTopic='';noteUnderstood=false;explanationResult=null;rescuePracticeResult=null;help=null;card=null;chat=[];chatTopic='';missionId=null;window.AllenReminders?.clearSummary();view='today';await render();return;}
 if(action==='confirm-delete'){const target=await loadProfile(db,button.dataset.id);main.innerHTML=`<section class="panel"><h1>Eliminar ${escape(target.profile.name)}</h1><p>Se borrará todo el progreso de este perfil en este navegador. Exporta una copia antes si quieres conservarlo.</p><div class="actions">${btn('Volver a perfiles','cancel-delete')}${btn('Eliminar este perfil definitivamente','delete',`data-id="${target.profile.id}"`,'danger')}</div></section>`;main.focus();return;}
 if(action==='cancel-delete'){await profiles();return;}
 if(action==='delete'){await deleteProfile(db,button.dataset.id);try{localStorage.removeItem(`allen-companion:${button.dataset.id}`);}catch{/* Preferences may be unavailable. */}if(state?.profile.id===button.dataset.id)state=null;view='profiles';help=null;card=null;chat=[];chatTopic='';missionId=null;window.AllenReminders?.clearSummary();await render();inform('Perfil eliminado de este navegador.');}
}
main.addEventListener('click',e=>{const button=e.target.closest('button[data-action]');if(button)guarded(()=>perform(button));});
main.addEventListener('input',e=>{if(e.target.closest('#answer-form')&&e.target.name==='answer'&&e.target.type==='text'&&activityDraft)activityDraft.input=e.target.value;if(e.target.id==='course-search'){courseQuery=e.target.value;main.querySelector('.course-grid').innerHTML=courseCards();}});
main.addEventListener('change',e=>{if(e.target.dataset.labValue!==undefined){const input=e.target,index=Number(input.dataset.labValue),value=Number(input.value);guarded(async()=>{const t=topicForSession();if(!t||state.session?.phase!=='lesson'||input.value.trim()===''||!Number.isFinite(value)||value<0||value>1000)throw Error('Usa una cantidad entre 0 y 1000.');const lab=state.learningLabs?.[t.id]??freshLab(t),values=[...lab.values];values[index]=value;if(labFor(t).kind==='fraction')values[0]=Math.min(values[0],values[1]);await mutate(s=>saveLab(s,t.id,{values}));await render({focus:false});main.querySelector(`[data-lab-value="${index}"]`)?.focus({preventScroll:true});});}if(e.target.dataset.match!==undefined&&activityDraft)activityDraft.matches[Number(e.target.dataset.match)]=e.target.value;if(e.target.id==='note-topic'){noteTopic=e.target.value;noteUnderstood=false;guarded(()=>render({focus:false}));}if(e.target.id==='chat-topic'){chatTopic=e.target.value;guarded(()=>render({focus:false}));}if(e.target.id==='course-subject'){courseSubject=e.target.value;main.querySelector('.course-grid').innerHTML=courseCards();}});
main.addEventListener('submit',e=>{e.preventDefault();const form=e.target,values=new FormData(form);guarded(async()=>{
 if(form.id==='reminder-form'){const time=String(values.get('time'));if(!/^\d{2}:\d{2}$/.test(time))throw Error('Elige una hora válida.');writeUiPreference('allen-reminder-time',time);const [hour,minute]=time.split(':').map(Number);window.AllenReminders?.enable(hour,minute);}
 if(form.id==='guided-form'){const message=String(values.get('message'));await askPrepared(findQuestion(message,state,chatTopic),message);}
 if(form.id==='learning-choice-form'){await mutate(s=>chooseCourse(s,String(values.get('course'))));view='learn';help=null;card=null;chat=[];chatTopic='';activityDraft=null;await render();inform('Materia seleccionada. Tu progreso en las demás sigue guardado.');}
 if(form.id==='profile-form'){state=await createProfile(db,Object.fromEntries(values));view='today';help=null;card=null;chat=[];chatTopic='';missionId=null;window.AllenReminders?.clearSummary();await render();inform('Perfil guardado en este dispositivo.');}
 if(form.id==='preferences-form'){await mutate(s=>{s.profile.name=String(values.get('name')).trim();chooseCourse(s,String(values.get('course')));s.preferences={...s.preferences,textSize:values.get('textSize')};});await render();inform('Preferencias guardadas.');}
 if(form.id==='accessibility-form'){await mutate(s=>{s.preferences={...s.preferences,textSize:values.get('textSize'),theme:values.get('theme'),reduceMotion:values.has('reduceMotion')};});await render({focus:false});inform('Accesibilidad guardada.');}
 if(form.id==='discovery-form'){await mutate(s=>saveDiscovery(s,values.get('topic'),String(values.get('note')),values.has('understood')));noteUnderstood=false;await render({focus:false});inform('Descubrimiento guardado en este perfil.');}
 if(form.id==='rescue-practice-form'){const r=rescueFor(state),q=r?.base.questions.find(q=>q.kind==='practice');if(!q)throw Error('Retoma tu actividad.');rescuePracticeResult=`${values.get('answer')===q.answer?'Esta base va bien.':'Revisemos la idea.'} ${q.feedback}`;await render({focus:false});}
 if(form.id==='explanation-form'){await mutate(s=>{explanationResult=saveReflection(s,topicForSession().id,values.get('rule'),values.get('example'));});await render({focus:false});}
 if(form.id==='lab-note-form'){const t=topicForSession();if(!t||state.session?.phase!=='lesson')throw Error('Abre una lección.');await mutate(s=>saveLab(s,t.id,{note:String(values.get('labNote'))}));await render({focus:false});inform('Explicación guardada en este perfil.');}
 if(form.id==='answer-form'){const q=questionById(state.session.questionIds[state.session.index]);const answer=['order','match'].includes(q.activity)?draftAnswer(q,activityDraft):String(values.get('answer'));if(q.activity==='match'&&new Set(activityDraft.matches).size!==q.pairs.length)throw Error('Usa cada descripción una sola vez.');rescuePracticeResult=null;await mutate(s=>submitAnswer(s,answer));help=null;await render();}
});});
menu.addEventListener('toggle',()=>menu.querySelector('summary').setAttribute('aria-expanded',String(menu.open)));
document.addEventListener('focusin',e=>{if(e.target.matches('#content input[type=text],#content textarea'))requestAnimationFrame(()=>e.target.scrollIntoView({block:'nearest'}));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus();}});
document.addEventListener('click',e=>{if(menu.open&&!menu.contains(e.target))menu.open=false;});
nav.addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)guarded(async()=>{view=b.dataset.view;await render();});});
document.querySelector('#settings-button').addEventListener('click',()=>guarded(async()=>{view=state?'settings':'profiles';await render();}));
document.querySelector('#profiles-button').addEventListener('click',()=>guarded(async()=>{view='profiles';help=null;card=null;chat=[];chatTopic='';missionId=null;window.AllenReminders?.clearSummary();await render();}));
function connection(){if(bundledAndroid){document.querySelector('#offline-status').textContent='Contenido incluido · sin Internet';return;}document.querySelector('#offline-status').textContent=offlineReady?(navigator.onLine?'Curso guardado · listo sin conexión':'Sin conexión · curso disponible'):(navigator.onLine?'Preparando curso para uso sin conexión…':'Sin conexión · descarga inicial pendiente');}
window.addEventListener('online',connection);window.addEventListener('offline',connection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.querySelector('#install-button').hidden=false;});
document.querySelector('#install-button').addEventListener('click',()=>guarded(async()=>{await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.querySelector('#install-button').hidden=true;}));
async function offline(){
 if(bundledAndroid){offlineReady=true;connection();return;}
 if(!('serviceWorker' in navigator)||!window.isSecureContext){document.querySelector('#offline-status').textContent='Instalación offline requiere HTTPS o localhost.';return;}
 try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;
  const channel=new MessageChannel();channel.port1.onmessage=e=>{if(e.data.type==='CACHE_STATUS'){offlineReady=e.data.ready;connection();if(!offlineReady)inform('El curso aún no se ha descargado completo. Recarga con conexión.',true);channel.port1.close();}};
  registration.active?.postMessage({type:'CACHE_STATUS'},[channel.port2]);
  registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)inform('Hay una actualización disponible. Cierra todas las pestañas de ALLEN y vuelve a abrir.');});});
 }catch{document.querySelector('#offline-status').textContent='No se pudo descargar el curso offline. Recarga con conexión.';}
}
let noteTopic='',noteUnderstood=false,rescuePracticeResult=null;
function accessibilitySettings(){const p=state.preferences??{};return `<section class="panel"><h2>Accesibilidad</h2><form id="accessibility-form"><label class="field">Apariencia<select name="theme">${[['system','Usar tema del dispositivo'],['light','Claro'],['dark','Oscuro']].map(([id,label])=>`<option value="${id}" ${(p.theme??'system')===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Tamaño del texto<select name="textSize"><option value="normal">Normal</option><option value="large" ${p.textSize==='large'?'selected':''}>Grande</option></select></label><label class="motion-option"><input name="reduceMotion" type="checkbox" ${p.reduceMotion?'checked':''}> Reducir movimiento</label><button type="submit" class="primary">Guardar accesibilidad</button></form><p class="small muted">La lectura de lecciones es opcional y utiliza una voz española local cuando el dispositivo la ofrece.</p>${speechAvailable()?btn('Detener lectura','stop-reading'):''}</section>`;}
function mixedPanel(){const count=activeCourse(state).topics.filter(t=>state.completed.includes(t.id)).length;if(count<2)return '<details class="panel"><summary>Repaso combinado</summary><p>Se activa cuando compruebes al menos dos temas de esta ruta. Así practicarás qué regla elegir en cada caso.</p></details>';return `<section class="panel"><h2>Repaso combinado</h2><p>Alterna hasta tres temas de esta ruta y decide qué regla aplicar. Priorizamos los temas con menor dominio estimado.</p>${count>=2?btn('Mezclar mis temas','mixed-review','','secondary'):'<p class="small muted">Se activa cuando compruebes al menos dos temas de esta ruta.</p>'}</section>`;}
function rescuePanel(){const r=rescueFor(state);if(!r)return '';const q=r.base.questions.find(q=>q.kind==='practice');return `<details class="panel rescue-panel" open><summary>Hagamos una pausa juntos</summary><img src="./assets/allen-explaining-v1.png" width="64" height="64" alt="Allen te acompaña"><p>Los últimos dos intentos en este tema costaron. Probemos una explicación más sencilla y recuperemos la base.</p><div class="actions">${btn('Más sencillo y otro ejemplo','rescue')}${btn('Recordar la base','rescue-base')}</div><details><summary>Ensayo con apoyo: ${escape(r.base.title)}</summary><p>${escape(r.base.simple)}</p><p>${escape(q.prompt)}</p><p class="small">Pista: ${escape(q.hints[0])}</p><form id="rescue-practice-form"><fieldset class="options"><legend>Prueba esta base</legend>${q.options.map(o=>`<label><input type="radio" name="answer" value="${escape(o)}" required><span>${escape(o)}</span></label>`).join('')}</fieldset><button type="submit">Revisar la base</button></form>${rescuePracticeResult?`<p role="status">${escape(rescuePracticeResult)}</p>`:''}<p class="small muted">Este ensayo con apoyo no desbloquea temas ni aumenta tu dominio. Después retoma tu actividad guardada.</p></details></details>`;}
function explainPanel(topic){const choices=explanationChoices(topic.id);return `<details class="panel"><summary>Explícamelo tú</summary><p>Objetivo: ${escape(topic.objective)} Elige la explicación que responde a este objetivo y el ejemplo que la justifica.</p><form id="explanation-form">${[['rule','¿Qué explicación corresponde?','text'],['example','¿Qué ejemplo demuestra por qué funciona?','example']].map(([name,label,key])=>`<fieldset class="options"><legend>${label}</legend>${choices.map(c=>`<label><input type="radio" name="${name}" value="${c.id}" required><span>${escape(c[key])}</span></label>`).join('')}</fieldset>`).join('')}<button type="submit" class="primary">Comprobar mi explicación</button></form>${explanationResult?`<p class="feedback ${explanationResult.correct?'':'error'}" role="status">${escape(explanationResult.text)}</p>`:''}<p class="small muted">Esta reflexión complementa la comprobación. Si el tema ya está comprobado y relacionas regla y ejemplo, cuenta para tu rango; no cambia tu dominio automáticamente.</p>${btn('Escribirlo con mis palabras','note-topic',`data-topic="${topic.id}"`)}</details>`;}
function notebook(){const topic=topicById(noteTopic)??topicForSession()??activeCourse(state).topics[0],note=state.notebook?.[topic.id];return hero('Cuaderno de descubrimientos','Lo que ahora entiendo','Guarda una idea con tus palabras. Tus notas viajan con la copia de este perfil.')+`<section class="panel"><form id="discovery-form"><label class="field">Tema<select id="note-topic" name="topic">${courses.map(c=>`<optgroup label="${escape(c.title)}">${c.topics.map(t=>`<option value="${t.id}" ${t.id===topic.id?'selected':''}>${escape(t.title)}</option>`).join('')}</optgroup>`).join('')}</select></label><p class="small">Idea importante: ${escape(topic.card.back)}</p><label class="field">Mi descubrimiento<textarea name="note" maxlength="800" rows="4" placeholder="Antes pensaba… ahora entiendo…">${escape(note?.text??'')}</textarea></label><label class="motion-option"><input type="checkbox" name="understood" ${noteUnderstood||note?.understood?'checked':''}> Comprendí un error que había cometido</label><button type="submit" class="primary">Guardar descubrimiento</button></form>${note?'<p class="small muted">Nota guardada en este perfil.</p>':''}${state.session&&state.session.phase!=='complete'?btn('Volver a mi actividad','resume'):''}</section><details class="panel"><summary>Mis ideas guardadas</summary>${Object.entries(state.notebook??{}).map(([id,n])=>`<article class="discovery"><h3>${escape(topicById(id).title)}</h3><p>${escape(n.text)||'Error comprendido.'}</p>${n.understood?'<span class="badge">Error comprendido</span>':''}</article>`).join('')||'<p>Tu primera nota aparecerá aquí.</p>'}</details>`;}

// APK only: guided tour and update panel (android-extras.mjs). The web PWA never loads it.
const androidExtras=bundledAndroid?await import('./android-extras.mjs').catch(()=>null):null;
try{db=await openStorage();const id=await activeProfile(db);state=id?await loadProfile(db,id):null;await render();offline();}catch{main.innerHTML='<section class="panel"><h1>No pudimos abrir el almacenamiento</h1><p>ALLEN necesita almacenamiento local para guardar tu progreso. Comprueba los permisos del navegador y recarga. No hemos borrado tus datos.</p></section>';nav.hidden=true;}

